<aside class="sidebar" aria-label="<?php esc_attr_e('Barra lateral','allg-editorial'); ?>"><?php if(is_active_sidebar('sidebar')): dynamic_sidebar('sidebar'); else: ?><section class="widget"><span class="eyebrow">Explore o blog</span><h2>Categorias</h2><ul><?php wp_list_categories(array('title_li'=>'','show_count'=>true)); ?></ul></section><section class="widget"><h2>Últimas publicações</h2><ul><?php $recent=new WP_Query(array('posts_per_page'=>5,'no_found_rows'=>true,'ignore_sticky_posts'=>true)); while($recent->have_posts()): $recent->the_post(); ?><li><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></li><?php endwhile; wp_reset_postdata(); ?></ul></section><?php endif; ?></aside>
